<?php
/**
 * Responsive images.
 *
 * Photos live in /assets/images/photos/ as {name}-{width}.webp, generated by
 * tools/make-image-variants.mjs, which also writes data/image-manifest.php —
 * the record of which widths actually exist. srcset is built from that
 * record, so it can never point at a file that is not on disk.
 */

if (!defined('ROOT_DIR')) {
    http_response_code(404);
    exit;
}

function image_manifest(): array
{
    return load_data('image-manifest');
}

/**
 * URL of one width variant; the closest available width at or below $want,
 * or the smallest one if all are larger.
 */
function photo_src(string $name, int $want = 800): string
{
    $entry = image_manifest()[$name] ?? null;
    if ($entry === null) {
        return '';
    }
    $chosen = $entry['widths'][0];
    foreach ($entry['widths'] as $w) {
        if ($w <= $want) {
            $chosen = $w;
        }
    }
    return '/assets/images/photos/' . $name . '-' . $chosen . '.webp';
}

function photo_srcset(string $name): string
{
    $entry = image_manifest()[$name] ?? null;
    if ($entry === null) {
        return '';
    }
    return implode(', ', array_map(
        static fn(int $w): string => asset('/assets/images/photos/' . $name . '-' . $w . '.webp') . ' ' . $w . 'w',
        $entry['widths']
    ));
}

/**
 * <img> with srcset, sizes, intrinsic width/height (so the box is reserved
 * before the file arrives) and lazy loading unless it is the LCP image.
 *
 * $opts: sizes, class, eager (bool), want (int, the fallback src width),
 *        priority (bool, default = eager: adds fetchpriority="high")
 */
function photo(string $name, string $alt, array $opts = []): string
{
    $entry = image_manifest()[$name] ?? null;
    if ($entry === null) {
        return '';
    }
    $want  = $opts['want'] ?? 800;
    $src   = photo_src($name, $want);
    $eager = !empty($opts['eager']);

    $attrs = [
        'src'      => asset($src),
        'srcset'   => photo_srcset($name),
        'sizes'    => $opts['sizes'] ?? '(min-width: 1024px) 33vw, (min-width: 768px) 50vw, 100vw',
        'width'    => (string) $entry['w'],
        'height'   => (string) $entry['h'],
        'alt'      => $alt,
        'class'    => $opts['class'] ?? '',
        'loading'  => $eager ? 'eager' : 'lazy',
        'decoding' => $eager ? 'auto' : 'async',
    ];
    if ($opts['priority'] ?? $eager) {
        $attrs['fetchpriority'] = 'high';
    }

    $html = '<img';
    foreach ($attrs as $key => $value) {
        // alt is always written: alt="" marks a decorative image.
        if ($value !== '' || $key === 'alt') {
            $html .= ' ' . $key . '="' . e($value) . '"';
        }
    }
    return $html . '>';
}

/**
 * A service's photo set (data/service-images.php): ['main' => name,
 * 'gallery' => [[name, alt], …]]. The main photo is always the first
 * gallery entry.
 */
function service_images(string $slug): array
{
    return load_data('service-images')[$slug] ?? ['main' => '', 'gallery' => []];
}

function service_main_photo(string $slug): array
{
    $set = service_images($slug);
    foreach ($set['gallery'] as [$name, $alt]) {
        if ($name === $set['main']) {
            return [$name, $alt];
        }
    }
    return $set['gallery'][0] ?? ['', ''];
}

/**
 * A service's installation clips (data/service-videos.php); $homeOnly keeps
 * only those flagged for the home page.
 */
function service_videos(string $slug, bool $homeOnly = false): array
{
    $videos = array_map(static fn(array $v): array => $v + ['service' => $slug], load_data('service-videos')[$slug] ?? []);
    return $homeOnly ? array_values(array_filter($videos, static fn(array $v): bool => !empty($v['home']))) : $videos;
}

/**
 * Every clip, keyed by its watch-page slug, each tagged with its service.
 */
function all_videos(): array
{
    $all = [];
    foreach (load_data('service-videos') as $serviceSlug => $videos) {
        foreach ($videos as $video) {
            $all[$video['slug']] = $video + ['service' => $serviceSlug];
        }
    }
    return $all;
}

function video_url(string $slug): string
{
    return '/' . $slug . '.php';
}

/**
 * The clip's MP4 and poster. Deliberately not cache-busted: the <video>
 * tag, VideoObject and video sitemap must name the identical URL, or
 * Google treats them as different videos.
 */
function video_src(array $video): string
{
    return '/assets/videos/' . $video['file'] . '.mp4';
}

function video_poster(array $video): string
{
    return '/assets/videos/' . $video['file'] . '-poster.webp';
}

/** ISO 8601 duration (PT1M5S) → seconds, for the video sitemap. */
function video_seconds(string $iso): int
{
    preg_match('/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/', $iso, $m);
    return (int) ($m[1] ?? 0) * 3600 + (int) ($m[2] ?? 0) * 60 + (int) ($m[3] ?? 0);
}

/** schema.org VideoObject for a clip — emitted on its watch page only. */
function video_schema(array $video): array
{
    return [
        '@context'         => 'https://schema.org',
        '@type'            => 'VideoObject',
        'name'             => $video['title'],
        'description'      => $video['description'],
        'thumbnailUrl'     => [base_url(video_poster($video))],
        'contentUrl'       => base_url(video_src($video)),
        'uploadDate'       => $video['date'],
        'duration'         => $video['duration'],
        'width'            => $video['w'],
        'height'           => $video['h'],
        'inLanguage'       => 'en-IN',
        'isFamilyFriendly' => true,
        'mainEntityOfPage' => base_url(video_url($video['slug'])),
        'publisher'        => ['@id' => base_url('/#business')],
    ];
}
